sp_BuscarProdutoPorId	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_BuscarProdutoPorId`(IN p_idProduto INT)\nBEGIN\n\n    SELECT\n\n        p.idProduto,\n\n        p.idEmpresa,\n\n        p.Nome                        AS nome,\n\n        p.Descricao                   AS descricao,\n\n        p.codProduto                  AS sku,\n\n        p.codBarras                   AS codigoBarras,\n\n        p.precoCusto,\n\n        p.precoVenda,\n\n        p.categoriaProduto_id         AS idCategoria,\n\n        p.uniMedida_id                AS unidade,\n\n        p.fAtivo,\n\n        p.dthCadastro,\n\n        COALESCE(e.Quantidade,    0)  AS qtdEstoque,\n\n        COALESCE(e.EstoqueMinimo, 0)  AS estoqueMinimo,\n\n        COALESCE(e.EstoqueMaximo, 0)  AS estoqueMaximo,\n\n        e.Local                       AS local\n\n    FROM Produto p\n\n    LEFT JOIN Estoque e\n\n        ON  e.IdProduto = p.idProduto\n\n        AND e.IdEmpresa = p.idEmpresa\n\n    WHERE p.idProduto = p_idProduto\n\n    LIMIT 1;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
